#define FORE(i, a, b) for(int i = (a); i <= (b); i++)
#define FORD(i, a, b) for(int i = (a); i >= (b); i--)
const long long INF64 = 1e18;
typedef long long ll;

struct Edge {
  int from;
  int to;
  int flow;
  int cost;

  Edge() {};

  Edge(int _from, int _to, int _flow, int _cost) 
    : from(_from), to(_to), flow(_flow), cost(_cost) {};
};

vector<Edge> allEdges;
const int MAXN = 1e6 + 7;
vector<int> adjList[MAXN];

ll totalCost = 0;
ll distArr[MAXN];
int parentNode[MAXN];
int parentEdgeIdx[MAXN];
int inQueueFlag[MAXN];

int sNode = MAXN - 2;
int tNode = MAXN - 1;

int residualCap(int eIdx) {
  return allEdges[eIdx].to - allEdges[eIdx].flow;
}

void shortestPath() {
  for (int i = 0; i < MAXN; i++) {
    distArr[i] = INF64;
    parentNode[i] = -1;
    parentEdgeIdx[i] = -1;
    inQueueFlag[i] = 0;
  }
  distArr[sNode] = 0;
  queue<int> q;
  q.push(sNode);
  inQueueFlag[sNode] = 1;
  while (!q.empty()) {
    int u = q.front(); q.pop();
    inQueueFlag[u] = 0;
    for (auto eIdx : adjList[u]) {
      if (!residualCap(eIdx)) continue;
      int cst = allEdges[eIdx].cost;
      int v = allEdges[eIdx].from;
      if (distArr[v] > distArr[u] + cst) {
        distArr[v] = distArr[u] + cst;
        parentNode[v] = u;
        parentEdgeIdx[v] = eIdx;
        if (!inQueueFlag[v]) {
          inQueueFlag[v] = 1;
          q.push(v);
        }
      }
    }
  }
}

void augmentFlow() {
  shortestPath();
  int cur = tNode;
  while (cur != sNode) {
    allEdges[parentEdgeIdx[cur]].flow++;
    allEdges[parentEdgeIdx[cur] ^ 1].flow--;
    cur = parentNode[cur];
  }
  totalCost += distArr[tNode];
}

void addEdge(int u, int v, int cap, int cst) {
  adjList[u].push_back(allEdges.size());
  allEdges.emplace_back(u, v, 0, cst);
  adjList[v].push_back(allEdges.size());
  allEdges.emplace_back(v, u, cap, -cst);
}

int n, m, k, c, d;
const int T = 101;

void buildGraph() {
  scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);
  for (int i = 0; i < k; i++) {
    int x; scanf("%d", &x);
    --x;
    addEdge(sNode, x, 1, 0);
  }
  for (int i = 0; i < T; i++) {
