import java.util.*;

public class Main {
    static class Edge {
        int from, to, flow, cost;
        Edge(int from, int to, int flow, int cost) {
            this.from = from;
            this.to = to;
            this.flow = flow;
            this.cost = cost;
        }
    }

    static final long INF64 = (long)1e18;
    static final int MAXN = 1000007;
    static List<Integer>[] adjList = new ArrayList[MAXN];
    static List<Edge> allEdges = new ArrayList<>();
    static long totalCost = 0;
    static long[] distArr = new long[MAXN];
    static int[] parentNode = new int[MAXN];
    static int[] parentEdgeIdx = new int[MAXN];
    static int[] inQueueFlag = new int[MAXN];

    static int sNode = MAXN - 2;
    static int tNode = MAXN - 1;

    static int n, m, k, c, d;
    static final int T = 101;

    static int residualCap(int eIdx) {
        return allEdges.get(eIdx).to - allEdges.get(eIdx).flow;
    }

    static void shortestPath() {
        Arrays.fill(distArr, INF64);
        Arrays.fill(parentNode, -1);
        Arrays.fill(parentEdgeIdx, -1);
        Arrays.fill(inQueueFlag, 0);
        distArr[sNode] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(sNode);
        inQueueFlag[sNode] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            inQueueFlag[u] = 0;
            for (int eIdx : adjList[u]) {
                if (residualCap(eIdx) == 0) continue;
                int cst = allEdges.get(eIdx).cost;
                int v = allEdges.get(eIdx).from;
                if (distArr[v] > distArr[u] + cst) {
                    distArr[v] = distArr[u] + cst;
                    parentNode[v] = u;
                    parentEdgeIdx[v] = eIdx;
                    if (inQueueFlag[v] == 0) {
                        inQueueFlag[v] = 1;
                        q.offer(v);
                    }
                }
            }
        }
    }

    static void augmentFlow() {
        shortestPath();
        int cur = tNode;
        while (cur != sNode) {
            allEdges.get(parentEdgeIdx[cur]).flow++;
            allEdges.get(parentEdgeIdx[cur] ^ 1).flow--;
            cur = parentNode[cur];
        }
        totalCost += distArr[tNode];
    }

    static void addEdge(int u, int v, int cap, int cst) {
        adjList[u].add(allEdges.size());
        allEdges.add(new Edge(u, v, 0, cst));
        adjList[v].add(allEdges.size());
        allEdges.add(new Edge(v, u, cap, -cst));
    }

    static void buildGraph() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();
        c = sc.nextInt();
        d = sc.nextInt();

        for (int i = 0; i < MAXN; i++) {
            adjList[i] = new ArrayList<>();
        }

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt();
            x--;
            addEdge(sNode, x, 1, 0);
        }

        for (int i = 0; i < T; i++) {
            addEdge(i * n, tNode, k, i * c);
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            x--;
            y--;
            for (int t = 0; t < T - 1; t++) {
                for (int j = 0; j < k; j++) {
                    addEdge(x + t * n, y + t * n + n, 1, d * (j * 2 + 1));
                }
            }
            for (int t = 0; t < T - 1; t++) {
                for (int j = 0; j < k; j++) {
                    addEdge(y + t * n, x + t * n + n, 1, d * (j * 2 + 1));
                }
            }
        }
        sc.close();
    }

    static void solve() {
        for (int i = 0; i < n; i++) {
            for (int t = 0; t < T - 1; t++) {
                addEdge(i + t * n, i + t * n + n, k, 0);
            }
        }
        for (int i = 0; i < k; i++) {
            augmentFlow();
        }
        System.out.println(totalCost);
    }

    public static void main(String[] args) {
        buildGraph();
        solve();
    }
}
